// Получаем текущий элемент
const item = $input.item;

// ✅ Если нет текста — возвращаем пустую структуру, чтобы не ломался цикл
if (!item.json?.message?.content) {
  return {
    json: {
      ...item.json,
      ratings: {},
      expertComment: ""
    }
  };
}

// Получаем текст от предыдущей ноды
const content = item.json.message.content;

// Объект для хранения оценок
const ratings = {};

// Регулярные выражения для поиска числовых оценок
const regexes = {
  "Связь с болью и потребностью": /Связь с болью и потребностью:\s*\*{0,2}(\d+)/i,
  "Описание точки Б через продукт": /Описание точки Б через продукт:\s*\*{0,2}(\d+)/i,
  "Итоговая оценка": /Итоговая\s*оценка:\s*\*{0,2}(\d+)/i
};

// Извлекаем оценки
for (const [key, regex] of Object.entries(regexes)) {
  const match = content.match(regex);
  if (match && match[1]) {
    ratings[key] = parseInt(match[1]);
  }
}

// Извлекаем комментарий эксперта
let expertComment = null;
const expertCommentStart = content.indexOf("Комментарий эксперта:");
if (expertCommentStart !== -1) {
  expertComment = content
    .substring(expertCommentStart + "Комментарий эксперта:".length)
    .trim();
}

// Возвращаем обновлённые данные
return {
  json: {
    ...item.json,
    ratings,
    expertComment
  }
};

// === Универсальный анализатор оценок ===
const item = $input.item;

// ✅ Если нет текста — возвращаем пустую структуру, чтобы не ломался цикл
if (!item.json?.message?.content) {
  return {
    json: {
      ...item.json,
      ratings: {},
      expertComment: ""
    }
  };
}

// 1️⃣ Берём текст из предыдущего узла
const content = $json.message?.content || "";

// 2️⃣ Инициализируем объект оценок
const ratings = {};

// 3️⃣ Регулярные выражения для поиска всех нужных блоков
const regexes = {
  // Этап 1
  "Контекст": /Контекст[:：]?\s*[*` ]{0,5}(\d+)/i,
  "Цель и точка Б": /Цель\s*и\s*точка\s*Б[:：]?\s*[*` ]{0,5}(\d+)/i,
  "Вытащил Боли": /Вытащил\s*Боли[:：]?\s*[*` ]{0,5}(\d+)/i,
  "Боли и триггеры": /Боли\s*и\s*триггеры[:：]?\s*[*` ]{0,5}(\d+)/i,

  // Этап 2
  "Резюме": /Резюме[:：]?\s*[*` ]{0,5}(\d+)/i,
  "Презентация": /Презентация[:：]?\s*[*` ]{0,5}(\d+)/i,
  "Точка Б\\+продукт": /Точка\s*Б\s*\+\s*продукт[:：]?\s*[*` ]{0,5}(\d+)/i,
  "Отработка возражения": /Отработка\s*возражения[:：]?\s*[*` ]{0,5}(\d+)/i,
  "Срочность": /Срочность[:：]?\s*[*` ]{0,5}(\d+)/i,
  "Договоренность след шаг": /Договоренность\s*след\s*шаг[:：]?\s*[*` ]{0,5}(\d+)/i,

  // Этап 3
  "Попытка закрытия": /Попытка\s*закрытия[:：]?\s*[*` ]{0,5}(\d+)/i,
  "Попытка закрытия на оплату": /Попытка\s*закрытия\s*на\s*оплату[:：]?\s*[*` ]{0,5}(\d+)/i,
  "Работа с возражениями через контекст": /Работа\s*с\s*возражениями\s*через\s*контекст[:：]?\s*[*` ]{0,5}(\d+)/i,
  "Усиление боли / FOMO / срочности": /Усиление\s*боли\s*\/?\s*FOMO\s*\/?\s*срочности[:：]?\s*[*` ]{0,5}(\d+)/i,
  "Договорённость по шагу и сроку оплаты": /Договор[её]нность\s*по\s*шагу\s*и\s*сроку\s*оплаты[:：]?\s*[*` ]{0,5}(\d+)/i,

  // Финал
  "Итоговая оценка": /Итоговая\s*оценка[:：]?\s*[*` ]{0,5}(\d+)/i
};

// 4️⃣ Извлекаем оценки
for (const [key, regex] of Object.entries(regexes)) {
  const match = content.match(regex);
  if (match && match[1]) {
    const clean = match[1].replace(/[^\d]/g, "");
    ratings[key] = clean ? parseInt(clean) : null;
  }
}

// 5️⃣ Извлекаем комментарий эксперта
let expertComment = null;
const start = content.indexOf("Комментарий эксперта:");
if (start !== -1) {
  expertComment = content.substring(start + "Комментарий эксперта:".length).trim();
}

// 6️⃣ Возвращаем результат
return {
  json: {
    ...$json,
    ratings,
    expertComment
  }
};

