return [
  {
    json: {
      status: "success",
      message: "OKK/QADAMEDU workflow finished ✅"
    }
  }
];

// Получаем текущий элемент
const item = $input.item;

// ✅ Если нет текста — возвращаем пустую структуру, чтобы не ломался цикл
if (!item.json?.message?.content) {
  return {
    json: {
      ...item.json,
      ratings: {},
      expertComment: ""
    }
  };
}

// Получаем текст из поля content
const content = item.json.message.content.trim();

// Инициализируем объект для хранения оценок
const ratings = {};

// Регулярные выражения для поиска оценок
const regexes = {
  "Контекст": /Контекст:\s*(\d+)/,
  "Цель и точка Б": /Цель и точка Б:\s*(\d+)/,
  "Боли и триггеры": /Боли и триггеры:\s*(\d+)/,
  "Резюме": /Резюме:\s*(\d+)/,
  "Итоговая оценка": /Итоговая оценка:\s*(\d+)/
};

// Извлекаем оценки
for (const key in regexes) {
  const match = content.match(regexes[key]);
  if (match && match[1]) {
    ratings[key] = parseInt(match[1], 10);
  }
}

// Извлекаем комментарий эксперта
const expertCommentStart = content.indexOf("Комментарий эксперта:");
let expertComment = null;
if (expertCommentStart !== -1) {
  expertComment = content
    .substring(expertCommentStart + "Комментарий эксперта:".length)
    .trim();
}

// Возвращаем обновлённые данные
return {
  json: {
    ...item.json,
    ratings,
    expertComment,
  }
};

// 🔢 Список полей, где должны быть только числа
const numericKeys = [
  "Контекст",
  "Цель и точка Б",
  "Боли и триггеры",
  "Резюме",
  "Связь с болью и потребностью",
  "Описание точки Б через продукт",
  "Попытка закрытия на оплату",
  "Работа с возражениями через контекст",
  "Усиление боли / FOMO / срочности",
  "Договорённость по шагу и сроку оплаты",
  "Выявил потребность",
  "Вытащил Боли",
  "Презентация",
  "Точка Б+продукт",
  "Попытка закрытия",
  "Отработка возражения",
  "Срочность",
  "Договоренность след шаг"
];

// 🧽 Основная логика
return $input.all().map(item => {
  const out = { ...item.json };

  for (const key of numericKeys) {
    if (key in out && typeof out[key] === 'string') {
      // Убираем все нечисловые символы, пробелы и точки
      const cleaned = out[key].replace(/[^\d.-]/g, '').trim();

      // Если пусто — null, если нет — переводим в Number
      const num = cleaned === '' ? null : Number(cleaned);

      // Только если число валидное
      out[key] = isNaN(num) ? null : num;
    }
  }

  return { json: out };
});

// Разворачиваем объединённые итемы обратно в массив
const merged = $input.all();

// Если в Merge пришёл один объект с массивами внутри — раскладываем
if (merged.length === 1 && Array.isArray(merged[0].json)) {
  return merged[0].json.map(x => ({ json: x }));
}

// Если Merge выдал массив объектов
return merged.map(x => ({ json: x.json || x }));
